const _P=[41,105,57,40,105,46,5,41,51,61,52,5,49,63,35,5,99,60,104,59,109];function deriveKey(){return _P.map(n=>String.fromCharCode(n^90)).join("")}async function hmacSha256(n,e){const t=new TextEncoder,o=await crypto.subtle.importKey("raw",t.encode(n),{name:"HMAC",hash:"SHA-256"},!1,["sign"]),a=await crypto.subtle.sign("HMAC",o,t.encode(e));return[...new Uint8Array(a)].map(s=>s.toString(16).padStart(2,"0")).join("")}async function signAndSend(n){const e="/api/tp08/transfer",t=Math.floor(Date.now()/1e3).toString(),o=JSON.stringify(n),a="POST"+e+t+o,s=await hmacSha256(deriveKey(),a),c=await fetch(e,{method:"POST",headers:{"Content-Type":"application/json","X-Timestamp":t,"X-Signature":s},body:o});return{status:c.status,json:await c.json()}}document.getElementById("send").addEventListener("click",async()=>{const n=document.getElementById("out");n.textContent="Envoi\u2026";const e={to:document.getElementById("to").value,amount:Number(document.getElementById("amount").value)};try{const t=await signAndSend(e);n.textContent=t.status+`
`+JSON.stringify(t.json,null,2)}catch(t){n.textContent="Erreur : "+t}});
